package com.tappylanguage.game

import android.content.res.AssetManager
import com.tappylanguage.engine.LanguagePack
import com.tappylanguage.engine.LevelPlanner
import com.tappylanguage.engine.Params
import com.tappylanguage.engine.SkillStore
import org.json.JSONObject

/** One audio attribution, generated by buildPack from INDEX.csv. */
data class AudioCredit(
    val text: String,
    val author: String,
    val license: String,
    val sourceUrl: String,
)

enum class WordState { NOT_STARTED, LEARNING, FLUENT }

data class WordProgress(val text: String, val recall: Double, val state: WordState)

object PackInfo {
    fun credits(assets: AssetManager, path: String): List<AudioCredit> = try {
        val array = JSONObject(assets.open(path).bufferedReader(Charsets.UTF_8).use { it.readText() })
            .getJSONArray("audio")
        (0 until array.length()).map { i ->
            val o = array.getJSONObject(i)
            AudioCredit(o.optString("text"), o.optString("author"), o.optString("license"), o.optString("sourceUrl"))
        }
    } catch (e: Exception) {
        emptyList()
    }

    /**
     * Every pack word with its recall (weakest skill, as the game uses), weakest first,
     * so the chips read as a bar: not started, learning (grey → yellow), then fluent (green).
     */
    fun progress(pack: LanguagePack, progressStore: ProgressStore, nowMs: Long): List<WordProgress> {
        val skills = SkillStore(pack)
        progressStore.load(skills)
        val planner = LevelPlanner(pack, skills)
        return pack.items.map { item ->
            val r = planner.wordRecall(item, nowMs)
            val state = when {
                !planner.wasPlayed(item) -> WordState.NOT_STARTED
                r >= Params.FLUENT_THRESHOLD -> WordState.FLUENT
                else -> WordState.LEARNING
            }
            WordProgress(item.text, r, state)
        }.sortedWith(compareBy({ it.state.ordinal }, { it.recall }))
    }
}
